import json

from pyvkteamsclient.stentor.base.client import BaseStentorClient
from pyvkteamsclient.tracer import tracer


class MailMethods(BaseStentorClient):
    @tracer.start_as_current_span("stentor.mail.mail_password")
    def mail_password(self, user_id: int):
        """
        Сигнализация об изменении пароля пользователем
        """
        return self.post(path="api/v1/mail/password", data={"user_id": user_id})

    @tracer.start_as_current_span("stentor.mail.mail_auth2factor")
    def mail_auth2factor(self, user_id: int, flag: int):
        """
        Сигнализация об изменении состояния 2-факторной авторизации
        """
        return self.post(
            path="api/v1/mail/auth2factor",
            data={"user_id": user_id, "flag": flag},
        )

    @tracer.start_as_current_span("stentor.mail.mail_session")
    def mail_session(self, user_id: int, sessions: list):
        """
        Сигнализация об изменении списка сессий
        """
        return self.post(
            path="api/v1/mail/session",
            data={"user_id": user_id, "sessions": json.dumps(sessions)},
        )

    @tracer.start_as_current_span("stentor.mail.mail_apwd")
    def mail_apwd(self, user_id: int, apwd_id: str):
        """
        Сигнализация об изменении пароля приложения
        """
        return self.post(
            path="api/v1/mail/apwd",
            data={"user_id": user_id, "apwd_id": apwd_id},
        )

    @tracer.start_as_current_span("stentor.mail.mail_phone")
    def mail_phone(self, user_id: int, phone: list):
        """
        Сигнализация об изменении пользовательского телефона
        """
        return self.post(path="api/v1/mail/phone", data={"user_id": user_id, "phone": phone})

    @tracer.start_as_current_span("stentor.mail.mail_mrimdis")
    def mail_mrimdis(self, user_id: int, flag: int):
        """
        Сигнализация об изменении статуса mrim-disabled
        """
        return self.post(path="api/v1/mail/mrimdis", data={"user_id": user_id, "flag": flag})

    @tracer.start_as_current_span("stentor.mail.mail_complaint")
    def mail_complaint(
        self,
        spam: str,
        _from: str,
        role_from: str,
        tmp: str,
        ctx: str,
        msg_txt: str,
        msg_ts: str,
        msg_chat: str,
        ua: str,
    ):
        """
        Сигнализация об срабатывании антиспама для сообщений
        """
        return self.post(
            path="api/v1/mail/complaint",
            data={
                "spam": spam,
                "from": _from,
                "role_from": role_from,
                "tmp": tmp,
                "ctx": ctx,
                "msg_txt": msg_txt,
                "msg_ts": msg_ts,
                "msg_chat": msg_chat,
                "ua": ua,
            },
        )

    @tracer.start_as_current_span("stentor.mail.mail_drop")
    def mail_drop(self, user_id: int, email: int):
        """
        Сигнализация об удалении пользователя
        """
        return self.post(path="api/v1/mail/drop", data={"user_id": user_id, "email": email})

    @tracer.start_as_current_span("stentor.mail.mail_profile")
    def mail_profile(self, user_id: int):
        """
        Сигнализация об изменении профиля пользователя
        """
        return self.post(path="api/v1/mail/profile", data={"user_id": user_id})

    @tracer.start_as_current_span("stentor.mail.mail_restore")
    def mail_restore(self, user_id: int, email: int):
        """
        Сигнализация об восстановлении пользователя
        """
        return self.post(
            path="api/v1/mail/restore",
            data={"user_id": user_id, "email": email},
        )
